<?php
namespace App\Services\Website;
use App\Models\{LandingAchievement,LandingFacility,LandingHighlight,LandingNews,LandingPageSetting,LandingProgram,LandingStatistic,LandingTestimonial,Personnel,SchoolProfile,Student};
class LandingPageService {public function data(bool $preview=false):array{$s=LandingPageSetting::values();$stats=LandingStatistic::active()->orderBy('sort_order')->get()->map(function($x){$x->resolved_value=match($x->source){'students'=>Student::where('status','active')->count(),'personnel'=>Personnel::where('is_active',true)->count(),'programs'=>LandingProgram::active()->count(),'achievements'=>LandingAchievement::active()->count(),default=>$x->manual_value};return $x;});return ['settings'=>$s,'school'=>SchoolProfile::first()??new SchoolProfile(['name'=>'MI Sultan Fatah','short_name'=>'MI Sultan Fatah']),'statistics'=>$stats,'highlights'=>LandingHighlight::active()->orderBy('sort_order')->get(),'programs'=>LandingProgram::active()->orderBy('sort_order')->get(),'facilities'=>LandingFacility::active()->orderBy('sort_order')->get(),'achievements'=>LandingAchievement::active()->where('featured',true)->orderBy('sort_order')->get(),'news'=>LandingNews::published()->latest('published_at')->limit(3)->get(),'testimonials'=>LandingTestimonial::active()->orderBy('sort_order')->get(),'preview'=>$preview];}}
